item.content:encoded:
.primary-menu > li > a{letter-spacing:0.8px;}

.rotateme{
		position: absolute;
    right: 0;
    top: -10px;    
    margin: 0 auto;
    animation-duration: 14s;
}
/* Animation Css */
.rotateme img{
  animation-name: rotateme;
  -webkit-animation-duration: 20s;
  animation-duration: 20s;
  -webkit-animation-iteration-count: infinite;
  animation-iteration-count: infinite;
  -webkit-animation-timing-function: linear;
  animation-timing-function: linear;
}
@keyframes rotateme {
  from {
    -webkit-transform: rotate(0deg);
            transform: rotate(0deg);
  }
  to {
    -webkit-transform: rotate(360deg);
            transform: rotate(360deg);
  }
}
@-webkit-keyframes rotateme {
  from {
    -webkit-transform: rotate(0deg);
  }
  to {
    -webkit-transform: rotate(360deg);
  }
}
.footer-wrap .container {
    max-width: 1170px;
}
.footer-wrap {
	padding: 40px 0;
}
footer div.footer-wrap .widget-title {
    font-weight: 400;
    text-transform: uppercase;
    font-size: 16px;
    letter-spacing: 1px;
}

/* Footer Button */
.bdt-advanced-button{
    border-style: none;
    border-radius: 4px 4px 4px 4px;
    box-shadow: 0px 8px 20px 0px rgba(0,0,0,0.35);
    padding:12px 20px 12px 20px;
    font-family: "Roboto", Sans-serif;
    font-size: 14px !important;
    font-weight: 500;
		background:#5351C5;
		color:#fff !important;
	  text-transform: uppercase;
    letter-spacing: 0.8px;
}

.fa, .fas {
   font-family: "FontAwesome";
   font-weight: 900;
}

/* Membership */
#pmpro_levels_table .pmpro_btn {
    color: #fff;
    border: none;
    border-radius: 3px;
    text-transform: none;
    background: #5351C5;
    box-shadow: 0 8px 15px rgba(0, 0, 0, 0.32);
}
.rtm_pmpro_levels_plan .rtm_levels_table_des ul li {
    padding: 5px;
    text-transform: none;
    font-size: 15px;
	  padding-left: 22px;
}

